@startuml

class Bookmaker {
  + name : string
  + acceptBet(bet : Bet) : void
  + calculateTotalWinnings() : double
  + calculateTotalLosses() : double
}

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + raceName : string
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner
Bookmaker "1" -- "*" Bet

@enduml

